// Comprueba la web, la API y el asistente. Solo devuelve un aviso cuando algo cambia de estado
// (se cae o se recupera); el estado anterior se guarda en los datos estáticos del flujo.
const checks = [
  { name: 'Web', url: 'https://pedidai.es/', ok: r => r.statusCode === 200 && String(r.body).includes('app-root') },
  { name: 'API', url: 'https://pedidai.es/api/users/me', ok: r => r.statusCode === 401 },
  { name: 'Asistente', url: 'https://pedidai.es/ai/health', ok: r => {
      const b = typeof r.body === 'string' ? JSON.parse(r.body || '{}') : r.body;
      return r.statusCode === 200 && b && b.status === 'ok';
  } },
];

const results = [];
for (const c of checks) {
  let ok = false, detail = '';
  // Dos intentos antes de dar el servicio por caído, para no avisar por un corte de un segundo
  for (let attempt = 1; attempt <= 2 && !ok; attempt++) {
    try {
      const r = await this.helpers.httpRequest({
        method: 'GET', url: c.url, timeout: 15000, returnFullResponse: true, ignoreHttpStatusErrors: true,
      });
      ok = c.ok(r);
      detail = `HTTP ${r.statusCode}`;
    } catch (e) {
      detail = e.message;
    }
    if (!ok && attempt === 1) await new Promise(res => setTimeout(res, 5000));
  }
  results.push({ name: c.name, url: c.url, ok, detail });
}

const state = $getWorkflowStaticData('global');
const down = results.filter(r => !r.ok).map(r => r.name).sort();
const before = (state.down || []).slice().sort();
state.down = down;
if (JSON.stringify(down) === JSON.stringify(before)) {
  return [];
}

const esc = s => String(s ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
const hora = new Date().toLocaleString('es-ES', { timeZone: 'Europe/Madrid', dateStyle: 'short', timeStyle: 'short' });
const filas = results.map(r => `<tr><td style="padding:4px 12px 4px 0">${r.ok ? '✅' : '❌'} <b>${esc(r.name)}</b></td>`
  + `<td style="padding:4px 12px 4px 0;color:#64748b">${esc(r.url)}</td><td style="padding:4px 0">${esc(r.detail)}</td></tr>`).join('');
const titulo = down.length ? `Fallo en PedidAI: ${down.join(', ')}` : 'PedidAI vuelve a funcionar';
const html = `<div style="font-family:Arial,sans-serif;max-width:640px;color:#0f172a">
  <h2 style="margin:0 0 12px">${esc(titulo)}</h2>
  <p style="margin:0 0 12px;color:#64748b">Comprobación de las ${hora}</p>
  <table style="border-collapse:collapse;font-size:14px">${filas}</table>
  ${down.length ? '<p style="margin-top:16px">Revisa el servidor: <code>systemctl status pedidai-api</code>, <code>docker compose ps</code> en /opt/apps/orderflow y los logs.</p>' : ''}
  <p style="margin-top:24px;font-size:12px;color:#94a3b8">Vigilancia de PedidAI (n8n, cada 5 minutos). Solo avisa cuando algo cambia.</p></div>`;
return [{ json: { subject: `${down.length ? '⚠️' : '✅'} ${titulo}`, html } }];
